import React, {
  createContext,
  useContext,
  useEffect,
  useState,
} from "react";

import en from "../locales/en";
import km from "../locales/km";

const LanguageContext = createContext();

const translations = {
  en,
  km,
};

const getCookie = (name) => {
  if (typeof document === 'undefined') return null;
  const match = document.cookie.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
  return match ? decodeURIComponent(match[1]) : null;
};

const setCookie = (name, value) => {
  if (typeof document === 'undefined') return;
  document.cookie = `${name}=${encodeURIComponent(value)}; path=/; max-age=31536000; SameSite=Lax`;
};

export const LanguageProvider = ({ children }) => {
  const [language, setLanguage] = useState(() => {
    const cookieLang = getCookie("app_language");
    if (cookieLang === "en" || cookieLang === "km") {
      return cookieLang;
    }

    return localStorage.getItem("language") || localStorage.getItem("admin_language") || "en";
  });

  useEffect(() => {
    localStorage.setItem("admin_language", language);
    localStorage.setItem("language", language);
    setCookie("app_language", language);

    document.documentElement.lang = language === "km" ? "km" : "en";
  }, [language]);

  // Listen for language changes from frontend_user or other tabs/ports
  useEffect(() => {
    const handleStorageChange = (event) => {
      if (event.key === "language" || event.key === "admin_language") {
        const newLang = event.newValue;
        if ((newLang === "en" || newLang === "km") && newLang !== language) {
          setLanguage(newLang);
        }
      }
    };

    const handleFocusSync = () => {
      const cookieLang = getCookie("app_language");
      if ((cookieLang === "en" || cookieLang === "km") && cookieLang !== language) {
        setLanguage(cookieLang);
        return;
      }
      const localLang = localStorage.getItem("language");
      if ((localLang === "en" || localLang === "km") && localLang !== language) {
        setLanguage(localLang);
      }
    };

    window.addEventListener("storage", handleStorageChange);
    window.addEventListener("focus", handleFocusSync);
    return () => {
      window.removeEventListener("storage", handleStorageChange);
      window.removeEventListener("focus", handleFocusSync);
    };
  }, [language]);

  const changeLanguage = (lang) => {
    if (lang === "en" || lang === "km") {
      setLanguage(lang);
      localStorage.setItem("language", lang);
      localStorage.setItem("admin_language", lang);
      setCookie("app_language", lang);
    }
  };

  const t = (key) => {
    const keys = key.split(".");

    let result = translations[language];

    for (const item of keys) {
      if (result?.[item] === undefined) {
        return key;
      }

      result = result[item];
    }

    return result;
  };

  return (
    <LanguageContext.Provider
      value={{
        language,
        changeLanguage,
        t,
      }}
    >
      {children}
    </LanguageContext.Provider>
  );
};

export const useLanguage = () => {
  const context = useContext(LanguageContext);

  if (!context) {
    throw new Error(
      "useLanguage must be used inside LanguageProvider"
    );
  }

  return context;
};

export default LanguageContext;
